import{z as B,x as i,o as t,c as p,q as r,j as l,D as e,d as A,s as n,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"TLA+","description":"","frontmatter":{"title":"TLA+","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tla-plus.md","filePath":"cs/tla-plus.md","lastUpdated":1791063341000}'),d={name:"cs/tla-plus.md"};function m(C,a,D,T,c,f){const s=i("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="tla" tabindex="-1">TLA+ <a class="header-anchor" href="#tla" aria-label="Permalink to &quot;TLA+&quot;">​</a></h1><div class="epigraph"><p>用状态与下一步关系写规格，模型检测穷举交错。Raft 与许多工业协议用它抓到实现者想不到的洞。它检查规格，不生成可部署代码。</p><footer>—— 据 Lamport, Specifying Systems；Newcombe et al., How Amazon Web Services Uses Formal Methods, CACM 2015；Ongaro Raft TLA+ 整理</footer></div><p>上一课<a href="/cs/rolling-upgrade">滚动升级</a>把混合版本交错变成现实。缺口是<strong>人脑画不全交错</strong>：Paxos 活锁、Raft 旧任期提交、成员变更。TLA+ 把<a href="/cs/replicated-state-machine">RSM</a>与共识写成变量与 Next。本课钉直觉，不教安装。分布式系统课程在此封口；后课安全进阶另起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TLA：时序逻辑 + 动作。规格 = 初始谓词 + Next + 公平性。安全：不变式（如「两主不能同任期提交不同值」）。活性：在公平调度下终发生。模型检测 TLC 在有限实例（2–5 节点、短日志）上穷举；超出则靠定理证明或缩小模型。</p><p><span class="marginnote">术语翻译：不变式是「任何时刻都必须为真」的断言，比如「系统里不会同时出现两个主」；活性是「好事终会发生」的断言，比如「每个请求最终被响应」。前者管「不坏事」，后者管「终成事」——两句话写得再像，检测方式完全不同。</span></p><p>缺口：测试给一条轨迹，检测给一类轨迹。Jepsen 打实现，TLA+ 打规格与算法；实现仍能写错。Amazon 用 TLA+ 查 DynamoDB/S3 内部协议故事见 CACM 2015。</p><p><span class="marginnote">Lamport 的书是源头。Raft 仓库带 TLA+。本课不发明 arXiv。PlusCal 是更像伪代码的前端。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写：变量（日志、term、角色），动作（超时、投票、追加）。不变式：选举安全、日志匹配。检查：从小 \\(n\\) 开始，加成员变更再跑。反例轨迹对照<a href="/cs/distributed-tracing">追踪</a>的思维，但是完备交错。</p><p><span class="marginnote">数字实例：两个进程各走 3 步，可能的交错就有 \\(\\binom{6}{3}=20\\) 种；5 个进程、每人几种角色一叠加，可达状态数立刻指数上升。这就是为什么 TLC 只能在 2–5 节点的缩小模型上跑——不是工具偷懒，是状态空间物理上放不下。</span></p>',11)),(t(),l(o,null,{default:e(()=>[n(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INIT%5B%22Init%22%5D%20--%3E%20NEXT%5B%22Next%20%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20NEXT%20--%3E%20INV%5B%22%E4%B8%8D%E5%8F%98%E5%BC%8F%3F%22%5D%0A%20%20INV%20--%3E%7C%22%E7%A0%B4%22%7C%20CE%5B%22%E5%8F%8D%E4%BE%8B%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20FAIR%5B%22%E5%85%AC%E5%B9%B3%E6%80%A7%22%5D%20--%3E%20LIVE%5B%22%E6%B4%BB%E6%80%A7%E6%80%A7%E8%B4%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"不要把 TLC 绿当成无限状态证明。有限模型是抽查。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"与证明助手：TLA+ 工业路径偏模型检测；Coq/Lean 偏构造证明。分布式课接 FLP：活性规格必须声明公平或部分同步假设，否则检测器会报「可不终止」——那是定理，不是工具坏了。",-1)),(t(),l(o,null,{default:e(()=>[n(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22%E5%88%9D%E5%A7%8B%E7%8A%B6%E6%80%81%20Init%22%5D%20--%3E%20A1%5B%22%E5%90%AF%E7%94%A8%E5%8A%A8%E4%BD%9C%20A%20%E5%88%86%E6%94%AF%22%5D%0A%20%20S0%20--%3E%20A2%5B%22%E5%90%AF%E7%94%A8%E5%8A%A8%E4%BD%9C%20B%20%E5%88%86%E6%94%AF%22%5D%0A%20%20A1%20--%3E%20S1%5B%22%E5%BE%97%E5%88%B0%E6%96%B0%E7%8A%B6%E6%80%81%22%5D%0A%20%20A2%20--%3E%20S2%5B%22%E5%BE%97%E5%88%B0%E6%96%B0%E7%8A%B6%E6%80%81%22%5D%0A%20%20S1%20--%3E%20V%7B%22%E8%AF%A5%E7%8A%B6%E6%80%81%E5%B7%B2%E6%8E%A2%E7%B4%A2%E8%BF%87%3F%22%7D%0A%20%20S2%20--%3E%20V%0A%20%20V%20--%3E%7C%22%E6%B2%A1%E8%A7%81%E8%BF%87%22%7C%20I%5B%22%E9%80%90%E6%9D%A1%E6%A3%80%E6%9F%A5%E4%B8%8D%E5%8F%98%E5%BC%8F%22%5D%0A%20%20V%20--%3E%7C%22%E8%A7%81%E8%BF%87%22%7C%20CUT%5B%22%E5%89%AA%E6%9E%9D%2C%E4%B8%8D%E5%86%8D%E5%B1%95%E5%BC%80%22%5D%0A%20%20I%20--%3E%7C%22%E5%85%A8%E9%83%A8%E6%88%90%E7%AB%8B%22%7C%20Q%5B%22%E5%85%A5%E9%98%9F%2C%E7%BB%A7%E7%BB%AD%E5%B1%95%E5%BC%80%E5%90%8E%E7%BB%A7%22%5D%0A%20%20I%20--%3E%7C%22%E8%A2%AB%E8%BF%9D%E5%8F%8D%22%7C%20CE%5B%22%E6%89%93%E5%8D%B0%E5%8F%8D%E4%BE%8B%E8%BD%A8%E8%BF%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>本课不写全部时序算子。也不把 TLA+ 当 LLM 对齐工具。</p><p>滚动与地理：把「新旧消息」做成 Next 的两种动作，比生产金丝雀更早看见双主。这是本课序收束的理由：前面所有协议都是状态机，TLA+ 是它们的共同语言。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不替代实现测试、混沌、Jepsen。后课默认：改共识与复制协议先有规格与小模型；绿不表示代码对。分布式系统从故障模型走到规格语言。安全进阶从 <a href="/cs/one-time-pad-perfect-secrecy">一次一密</a> 另起，不把 TLA+ 当加密证明。</p><p><span class="marginnote">常见误区：初学者容易以为 TLC 全绿等于「这个系统没有 bug」。实际上它只证明了「在这份规格、这组模型参数（节点数、日志长度）下」性质成立——实现的人把规格抄错一行，或者真实负载超出模型范围，绿纸就作废了。</span></p><p>分布式系统从故障模型走到规格语言。中间每一课都是某一种状态机与某一种对手。TLA+ 把对手写成 Next 里的分支。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TLA+：状态、Next、不变式；TLC 穷举有限实例。</li><li>安全与活性分开写；活性要公平/同步假设。</li><li>查规格与算法，不替代实现对抗测试。</li><li>出处：Lamport, <em>Specifying Systems</em>；Newcombe et al., CACM 2015；Raft TLA+。</li></ul>',8))])}const h=B(d,[["render",m]]);export{L as __pageData,h as default};
